INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Are You Smarter Than a 5th Grader', 'Are you Smarter Than a 5th Grader? demonstrates exactly how much adults have forgotten since their elementary school days. Art? Math? Social Studies? It''s all up on the chalkboard again as adult contestants team up with students to answer questions based on material from elementary school textbooks.' FROM games WHERE igdb_id = 35440 ON CONFLICT (game_id, language_code) DO NOTHING;
