INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Forge Quest', 'Forge Quest is a dungeon crawling rpg set in a voxel world. Explore the land full of chickens on a light hearted quest to become a hero. Delve deep into the randomly generated dungeons to battle monsters, find treasure and craft your equipment. Invite your friends to join your world and help you in your adventure.' FROM games WHERE igdb_id = 16652 ON CONFLICT (game_id, language_code) DO NOTHING;
