INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Prometheus: The Fire Thief', 'Prometheus - The Fire Thief is an action adventure game set in ancient Greece. As the player you assume control of the titan Prometheus. After stealing the fire from the Gods of mount Olympus, Prometheus must travel all across Greece and outside its borders, battling hideous monsters.' FROM games WHERE igdb_id = 35433 ON CONFLICT (game_id, language_code) DO NOTHING;
