INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'HueBots', 'HueBots is a deceptively challenging top-down puzzle game. You control a team of colorful robots that will only interact with objects that match their color; they will also keep moving in one direction until they collide with something that matches their color. Use your robots to unlock doors, push away blocks, shift colors, and work as a team to help aid your special black and white robot to the finish!' FROM games WHERE igdb_id = 34589 ON CONFLICT (game_id, language_code) DO NOTHING;
