INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Devouring Stars', 'What if you could unhook the stars and fight your battles with black holes? With its mix of adaptative unit combination, space resource harvesting as well as visual and audio refinement, Devouring Stars aspires to bring a different scope to the RTS genre.' FROM games WHERE igdb_id = 35663 ON CONFLICT (game_id, language_code) DO NOTHING;
