INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Balls', 'Star Balls is an awesome puzzler game that follows three stowaways on a spaceship trying to use their unique skills to navigate the craft and escape. The 3D visuals are incredibly rich, the story is good, there are plenty of levels, power-ups and it’s a must play game.' FROM games WHERE igdb_id = 35370 ON CONFLICT (game_id, language_code) DO NOTHING;
