INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doomed''n Damned', 'Doomed''n Damned is an action game based on retro/classic platform games from Arcades and 16 bit consoles, but revised to the HD era. The level design, characters, plot and difficulty have a lot of influence from the late 80s and early 90s games. The development and production is by arc-gen, an one man indie game studio.' FROM games WHERE igdb_id = 34918 ON CONFLICT (game_id, language_code) DO NOTHING;
