INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Flooded Tower', 'A Goomba was exploring through a giant lava cave, which is filled with a lot of treasure! In this latest exploration, the Goomba found a clock tower, which wasn''t there in all of the Goomba''s previous visits to the lava cave! As a river of lava is flowing after the Goomba, he went inside the clock tower. Though, the Goomba will have to keep moving! Because the lava is now rising, flooding the clock tower!' FROM games WHERE igdb_id = 321709 ON CONFLICT (game_id, language_code) DO NOTHING;
