INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fingertip-tennis', 175060, '2015-07-30', NULL, NULL, NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fingertip Tennis', 'Fingertip Tennis is not the most realistic tennis simulator. It is not the most precise. It doesn’t pay ATP licenses so it doesn’t feature famous tennis players (but it almost does). Fingertip Tennis is not the ultimate tennis game but it is one hundred times funnier and more original than any other out there. What do you play your mobile and tablet with? With fingers, don’t you? Then we want your fingers to feel like at home in the best tennis courts around the world. Let your fingers play in London, New York, Paris and other exciting tournaments in clay, grass and hardcourts. Let your fingers play with Rafinger Nadal, Dafing Ferrer, Fingerena Williams and other (almost) stars. We told you we haven’t got licenses so these fingers only seem famous. Do you want even more fun? Play also with some crazy special characters: Old Finger, Angry Finger, Band Aid or even Fingeracca.' FROM games WHERE igdb_id = 175060 ON CONFLICT (game_id, language_code) DO NOTHING;
