INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dirt Stooge', 'A dull platform shooting game, inspired by the out of bounds background landscapes in other games. I wanted the game to be generally basic and empty, but also tried to make it feel substantial with the audio and visual style.' FROM games WHERE igdb_id = 345866 ON CONFLICT (game_id, language_code) DO NOTHING;
