INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chronicles of the Witches and Warlocks', 'Chronicles of the Witches and Warlocks is an adventure game about a lawyer, Kathleen Wilson, who has to hold her own investigation in order to free her beloved. She''ll have to solve a plethora of puzzles before she can learn what really happened. Collect photographs, notes, slides - anything that might be useful in your investigation. Record all the facts and clues in your notebook - they could come in handy later. It isn''t hard to hit a dead end in an investigation, but don''t panic - you can use a hint.' FROM games WHERE igdb_id = 34614 ON CONFLICT (game_id, language_code) DO NOTHING;
