INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Afterlife Empire', 'Hey, you just died. But don''t worry! All the major religions were wrong! Instead of ascending to a new plane of existence, you are now self-employed in the Afterlife with your own haunted house to run. Keep people just scared enough to keep believing in you, but not enough to alert the local authorities.' FROM games WHERE igdb_id = 35320 ON CONFLICT (game_id, language_code) DO NOTHING;
