INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mega Man 42', 'A Mega Man fan game by Servadac. The game is made in the style of the original Mega Man for NES. Because of this many of the newer features are not to be found in the game, such as Mega Man''s slide and charge-up buster. There are no E-tanks either. This to preserve the challenge of the game instead of watering it out with features that do not add to the gameplay, and instead detract from it by making it too easy.' FROM games WHERE igdb_id = 322284 ON CONFLICT (game_id, language_code) DO NOTHING;
