INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NekoChan Hero Collection', 'NekoChan Hero Collection - a collection of games from the NekoChan series. The franchise is inspired by old school platforms like the Mario series. The collection includes three games: Ninja World 1 and 2, and Neko Land. The gameplay of all three games is an old-school platformer. The main character is a ninja kitty named Neko.' FROM games WHERE igdb_id = 210754 ON CONFLICT (game_id, language_code) DO NOTHING;
