INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Redshift Blueshift', 'Redshift Blueshift is a tournament-ready pong-like 2D shooter in which two pilots fight for glory in their variable paddle ships! Power up your shields, unleash a horde of drones and homing missiles on your opponent and keep the hyper-ball in play! Supports local multiplayer and single player vs AI. Gamepad strongly recommended.' FROM games WHERE igdb_id = 35314 ON CONFLICT (game_id, language_code) DO NOTHING;
