INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Mystery of a Lost Planet', 'The crew of a marooned spaceship must uncover the secrets of an unknown planet to survive. After a crash landing on the lost planet, you''re left with many unanswered questions. What was the mysterious force that seems to have pulled your ship into the planet and what are its intentions? The journey to answer these questions will be challenging but you cannot give up, because if you fail the crew will never see their home planet again!' FROM games WHERE igdb_id = 34522 ON CONFLICT (game_id, language_code) DO NOTHING;
