INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Country Tales', 'Country Tales is a time management and strategy adventure set in the charming Wild West town of Sunset Hills. Join Ted, a hopeful young man who moves to the countryside after finishing university and finds himself helping the mayor while falling for his fiancée, Catherine. Build, manage resources, solve quests, and navigate through romantic entanglements and unexpected twists. With colorful visuals, engaging story progression, and multiple gameplay modes, Country Tales offers a lighthearted challenge for casual gamers of all ages.' FROM games WHERE igdb_id = 34633 ON CONFLICT (game_id, language_code) DO NOTHING;
