INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aspectus: Rinascimento Chronicles', 'Netherlands, 1520. The Destroyers of the Art come out of paintings and materialize from statues, they come to infect the Art and wreck the city. To trap them, help Mr. Bruesen create the Aspectus, the Perfect Painting, before the time runs out. Find the sect of the amorphous creatures and destroy it.' FROM games WHERE igdb_id = 35938 ON CONFLICT (game_id, language_code) DO NOTHING;
