INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Necromonads', 'Space Colony Alert Bulletin! The Necromonads are at it again!! Colonists must in a orderly fashion proceed to the nearest shelter while the highly trained star pilot provides cover. Inspired by classic arcade shooters but with a twist. Captured colonists become infected and spread it to others. stop the Necromonads infection invasion now!' FROM games WHERE igdb_id = 34743 ON CONFLICT (game_id, language_code) DO NOTHING;
