INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Home From Work 3', 'You arrive home after a long day at work to your new modern day home. You spent a few days at the home and everything seemed to be normal; but, today, you begin to discover paranormal occurrences. Walking, talking, strange noises and even moving furniture begin to happen more frequently. It is now time to see what evil spirit lurks in the third home in Home from work 3.' FROM games WHERE igdb_id = 213372 ON CONFLICT (game_id, language_code) DO NOTHING;
