INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Free Fur All: We Bare Bears', 'Experience a lively collection of minigames with Free Fur All, where your mission is to help Grizz, Panda, and Ice Bear navigate their amusing adventures in the Bay Area. These engaging games include racing to the finish line, sprucing up selfies, and more, offering hours of entertainment. Immerse yourself in the charming world of three bear brothers as they seek fun while learning and growing in life.' FROM games WHERE igdb_id = 373234 ON CONFLICT (game_id, language_code) DO NOTHING;
