INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Out of Reach', 'You’re a castaway stranded in the middle of nowhere. The storm is gone, the worst certainly not. Look for food and resources, craft gear, make a shelter. These are the basics, you will need much more to stay alive on this cut-off-the-world, yet not desert island. Build and burn, sail and explore, stay out of reach!' FROM games WHERE igdb_id = 17915 ON CONFLICT (game_id, language_code) DO NOTHING;
