INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sakura-no-uta-sakura-no-mori-no-ue-wo-mau', 135568, '2015-10-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaa9x.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4ex6.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sakura no Uta: Sakura no Mori no Ue wo Mau', 'Spring. After the death of his father - a world-famous artist - left him without any living relatives, protagonist Kusanagi Naoya is put under the care of his friend Natsume Kei''s family. There, his homeroom teacher Natsume Ai, and Kei''s younger sister - the actress Natsume Shizuku - await him in turn. And with the arrival of the new school term, Misakura Rin - Naoya''s childhood friend who transferred long ago - reappears right before him.
