INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Candlewind: Nights & Candles', 'The Legend of Candlewind: Nights & Candles returns to the traditions of old role-playing legends. Go up against the forces of evil in hand-drawn dungeons, step by step. Following in the footsteps of classic dungeon crawlers, players will take part in turn-based battles that will put their skills to the ultimate test. Only true role-playing gamers will have any chance of survival!' FROM games WHERE igdb_id = 17910 ON CONFLICT (game_id, language_code) DO NOTHING;
