INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Quadle', 'A brand new arcade puzzler from Gamesare Studios, Envoking the memory of classic arcade cabinet games but adding a new twist. Jump on the blocks as the titular character Quadle, changing the block colors till they are red. Once red they fall away. Eliminate all blocks on the screen to go to the next level. Be careful not to corner yourself into a situation where you can jump to the next block.' FROM games WHERE igdb_id = 34926 ON CONFLICT (game_id, language_code) DO NOTHING;
