INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monster Hunter Diary: Poka Poka Palico Village DX', 'Monster Hunter Diary: Poka Poka Palico Village DX is the 3DS version of a spin-off installment in the Monster Hunter series, originally developed by FromSoftware and published by Capcom for the PlayStation Portable. The player gives orders to the felynes to progress to the end of quests instead of having direct control over them. The game uses a more cartoonish art style as opposed to the more realistic style seen in the main Monster Hunter games. More emphasis is placed on style and village management.' FROM games WHERE igdb_id = 84600 ON CONFLICT (game_id, language_code) DO NOTHING;
