INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Downpour', 'Downpour is a hardcore 2D Base survival game. A simple game in concept, but a complexity in practice. Protect an Antenna that is being built from endless enemies so you can contact home. All the while managing closely tied resources. Death will probably come many times.' FROM games WHERE igdb_id = 35221 ON CONFLICT (game_id, language_code) DO NOTHING;
