INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Captain''s Log', 'The Captain''s Log sets the player as the captain of a star ship that has been lost in space. Find your way home, scavenging for resources, upgrading your ship, embarking on dangerous missions and scouting out worm holes. As you play, the captain will record in his/her log updates about the day, dynamically reacting to the events of the story.' FROM games WHERE igdb_id = 135314 ON CONFLICT (game_id, language_code) DO NOTHING;
