INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SpongeBob Excludes Squidward', 'An unofficial Spongebob themed puzzle game, very similar to the Flash game "Red Remover." The game features 20 levels in which the player must use the mouse to remove any and all Squidward shapes (either circles or squares) from the screen, while simultaneously preventing any SpongeBob shapes from falling off the screen. Once all the Squidward shapes have been removed, the level is completed, and the player is given a star ranking based on their performance.' FROM games WHERE igdb_id = 388139 ON CONFLICT (game_id, language_code) DO NOTHING;
