INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The World End Eclipse', 'The World End Eclipse is an upcoming free-to-play online theater RPG. It is set in a ruined world destroyed by a war between dragons. People who were chased off the land built a city on the back of a dragon carcass and are forced to deal with conflicts caused by people and attacking goblins alike.' FROM games WHERE igdb_id = 13546 ON CONFLICT (game_id, language_code) DO NOTHING;
