INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'D Series Off Road Driving Simulation', 'D Series is an off road driving simulation with custom track editor built into the Steam Workshop. It was originally released in 2015 and completely rebuilt for 2017 with all new vehicles and a new controller input system. The simple in-game track editor will allow you to create custom Race Tracks, Rock Crawling Rubicons and Off Road Fun Parks in minutes and even share them on the Steam Workshop. So sit down, strap in and see if you have what it takes to tame these wild off road machines. Built for todays hightech Force Feedback steering systems and Available for Windows, Mac and Linux.' FROM games WHERE igdb_id = 35478 ON CONFLICT (game_id, language_code) DO NOTHING;
