INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deer Hunter 2018', 'From the creators of Deer Hunter 2014! Return to the wild and hunt across the globe in the world’s greatest hunting experience. Pursue trophies in unique and beautiful locations that span the globe from Alaska to Zimbabwe. Hunt animals so real they nearly jump off the screen! Track down and bag the world’s most exotic and elusive game. Collect and customize your firearms with scopes, magazines, barrels, and stocks as you perfect your weapons for each hunt.' FROM games WHERE igdb_id = 106291 ON CONFLICT (game_id, language_code) DO NOTHING;
