INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('i-slay-zombies-vr-shooter', 174343, '2015-12-21', NULL, NULL, NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I Slay Zombies: VR Shooter', 'The Z-virus is real and the zombie apocalypse is upon us. I Slay Zombies: VR Shooter places you in the middle of the fight against the undead. In this exciting virtual reality (VR) horror shooter you will have to use your arsenal of deadly weapons to the fullest in order to survive. Don’t let them eat your brain and always follow rule #1: The best zombie is a dead zombie! Grab your machine gun, aim and shoot the raging zombies through your motions alone. Make use of the full 360° view to keep an eye on the threat. Slow them down with a precise leg shot from your sniper rifle or finish them off with your trusty chain saw! Withstand wave after wave as the horde of the undead comes rushing towards you and face a terrifying boss to escape. Survival is a bloody business!' FROM games WHERE igdb_id = 174343 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 174343 AND ge.slug = 'simulator' ON CONFLICT DO NOTHING;
