INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('spirit-run-fire-vs-ice--1', 17584, '2015-01-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co40l7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar16zt.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spirit Run: Fire vs. Ice', 'Get ready for the run of a lifetime. In this endless platformer you play an elemental spirit that has the ability to change form. Spirit Run: Fire vs Ice is inspired by games such as the platformer Canabalt and the classic shoot ‘em up Ikaruga. Jump, slide and transform to reach new heights. Use your spirit powers to change between ice and fire form. Match the elements to dash through fire and water hazards. The goal is to get as far as possible and to collect elemental orbs to multiply your score. Numerous obstacles need to be overcome if you want to compete with the best on the leaderboards. Spirit Run: Fire vs Ice features beautiful pixel art and 8-bit retro soundtrack that takes you back to the golden age of videogames.
