INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Samurai_Jazz', 'An action/adventure game taking ques from both film-noir and samurai-drama''s of old, "samurai_jazz" takes players on an adventure through an enigmatic city, engaging in sword-fights, encounters with mythological beings, and quirky dialog with the local inhabitants presented with a pseudo 8-bit style. While action remains the central focus, a bit of detective work and puzzle-solving will become necessary while adventuring in this pixelated nightmare.' FROM games WHERE igdb_id = 35829 ON CONFLICT (game_id, language_code) DO NOTHING;
