INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marvel Puzzle Quest: Dark Reign', 'The award winning match-3 puzzle gameplay meets Marvel’s biggest Super Heroes and Super Villains in the most epic puzzle adventure. Combine your favorite characters from the Marvel Universe (including Iron Man, Hulk, Thor, and Venom) with deep RPG leveling, episodic events written by Marvel writers, and much more. Put your squad to the test in battles against players in both online and local multiplayer to compete for the top of the leaderboards. Unleash your inner Super Hero and wage war against your enemies before Norman Osborn and his minions reign supreme!' FROM games WHERE igdb_id = 82445 ON CONFLICT (game_id, language_code) DO NOTHING;
