INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slugterra: Dark Waters', 'Based on the Slugterra animated series, Slugterra: Dark Waters, players take on the role of Eli Shane to explore the underground world of Slugterra and protect its lands from the forces of evil. The game combines real-time strategic combat with the use of “slugs,” collectible creatures with special abilities that can be evolved for greater effectiveness in battle. Featuring a plot inspired by the series, the game offers varied missions, diverse environments and strategic challenges, remaining faithful to the animated universe through detailed graphics and engaging gameplay.' FROM games WHERE igdb_id = 327630 ON CONFLICT (game_id, language_code) DO NOTHING;
