INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Predator Simulator', 'Predator Simulator is an action arcade RPG packed with endless gameplay and new missions for every game session. On a quest to become a true Lion born, you get to save the planet by wiping out humanity from the face of the earth. Yeah.... didn''t you always want to do that anyway? Now is your chance! Unlock the hidden uncharted territory outside the game world by becoming a true Lionborn, where you can find secret journal entries from the game developer. We hope you will enjoy knowing more about the back story of this game and how it was made.' FROM games WHERE igdb_id = 35303 ON CONFLICT (game_id, language_code) DO NOTHING;
