INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Fool', 'Who said that only brave knights on white stallions can become Heroes? Witness the incredible adventures of a rustic Fool; travel with him to a fascinating world and help him save the beautiful princess Catherine from the jaws of a terrible dragon. A Hero lives in every one of us! Journey to set your Hero free!' FROM games WHERE igdb_id = 36130 ON CONFLICT (game_id, language_code) DO NOTHING;
