INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'New Atelier Rorona: The Alchemist of Arland', 'This remake of Atelier Rorona for the Nintendo 3DS was released exclusively in Japan in 2015 and features a new chibi art style alongside a new battle system. The base game content is mostly the same as Atelier Rorona Plus on other platforms, with the exception of the exclusive game mode "Atelier Astrid".' FROM games WHERE igdb_id = 82105 ON CONFLICT (game_id, language_code) DO NOTHING;
