INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Gate', 'The Gate is a 3D Card Collecting Game with elements of RTS and RPG. Originally available on mobile and via the web, The Gate was brought to Steam with the help of Steam users via Project Greenlight. Now heading into its 2nd year online, The Gate features PvP tournaments, where you can put your Card Collection into battle against other players. Or you could just download it (for free) and give it a negative review, because you''re the Steam Police and you hate F2P P2W (insert other stuff you hate) type of games.' FROM games WHERE igdb_id = 35727 ON CONFLICT (game_id, language_code) DO NOTHING;
