INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Treasure Hunter Man 2', 'THM2 is a retro metroidvania. Acquiring new equipment and upgrades opens up more explorable areas in all sorts of places. This adventure platformer takes you from the depth of a sunken underground city to the ruins in the sky all the way beyond the realms of reality. The game has multiple endings and additional challenges if you''re really good at treasure hunting. A normal playthrough will take about 4-5 hours, and with the optional content about 7 to 8 hours.' FROM games WHERE igdb_id = 102977 ON CONFLICT (game_id, language_code) DO NOTHING;
