INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SpongeBob: Sponge on the Run', 'SpongeBob and Plankton are in a race to find the lost Krabby Patty formula somewhere in Bikini Bottom, Apocalyptic Bikini Bottom and a real-world beach. When he’s not running, SpongeBob is flying, floating in a bubble, or has Plankton jumping around his surreal imagination. And when the running gets tough, the tough get heroic! SpongeBob becomes Super SpongeBob to knock through any obstacle in his way!' FROM games WHERE igdb_id = 87335 ON CONFLICT (game_id, language_code) DO NOTHING;
