INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tic-Tac-Toe 3D', 'The game is similar to the traditional game of Tic Tac Toe, but is played on three 3x3 grids stacked vertically. To score a point, a player must place three of their symbols on 3 squares that line up vertically, horizontally, or diagonally, on a single grid, or spaced evenly over all three grids. The winner is the one who scored the more points when all symbols have been placed.' FROM games WHERE igdb_id = 104747 ON CONFLICT (game_id, language_code) DO NOTHING;
