INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Afterfall: Reconquest', 'Afterfall: Reconquest (previously titled as Afterfall: Pearl of the Wastelands) is an episodic story-driven third-person shooter video game with action and adventure elements, developed by Intoxicate Studios and published by Nicolas Entertainment Group for Microsoft Windows. It is the sequel to the video game Afterfall: Insanity. The game will consist of 9 episodes. The first episode was released on February 19, 2015.' FROM games WHERE igdb_id = 18961 ON CONFLICT (game_id, language_code) DO NOTHING;
