INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Striker Arena', 'Join Vikings, Gladiators and Samurai to play the Soccer of the Gods! Striker Arena is a 3D tactical-action fantasy soccer game with warriors fighting in arenas. No rules! Even allows 2 people to play side-by-side on one device at the same time!' FROM games WHERE igdb_id = 175158 ON CONFLICT (game_id, language_code) DO NOTHING;
