INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wangan Midnight Maximum Tune 5DX', 'Wangan Midnight Maximum Tune 5DX (also known as Maximum Tune 5DX or simply Maxi 5DX) is an arcade racing game developed and published by Namco, based on the Wangan Midnight manga. As the eighth installment in the Wangan Midnight arcade series, this update introduces two foreign car manufacturers, Dodge and Audi, to the Japanese version, which were previously available only in the international versions of Wangan Midnight Maximum Tune 5. Additionally, two courses from the Japanese version of Maximum Tune 5, Sub-Center Ikebukuro and Shinjuku/Shibuya, were introduced to the international version. The game also debuts the new Kobe course.' FROM games WHERE igdb_id = 315270 ON CONFLICT (game_id, language_code) DO NOTHING;
