INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Leonardo''s Cat', 'Leonardo''s latest invention, the Automaton, has been stolen by his devious arch-enemy Michelangelo. You must help Scungilli, Leonardo’s brave and long suffering cat, as he searches the ancient city for the Automoton, negotiating ominous obstacles and terrifying traps as he goes. Use your wits and an arsenal of da Vinci’s cunning inventions to negotiate levels and guide Scungilli to safety. But one false move – and it’s back to the drawing board!' FROM games WHERE igdb_id = 175398 ON CONFLICT (game_id, language_code) DO NOTHING;
