INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Celia''s Quest', 'Not long after Celia leaves her home to go on an adventure (and maybe, just maybe, to avoid getting married to Ced the creep) she finds herself in the village of Villageville, where she meets another runaway. Just as they are deciding to go search for adventure together, a group of remarkably rude bandits show up and kidnap Celia''s new friend! Now it''s up to Celia to save her friend, prove herself to the villagers in Villageville, and beat up all kinds of strange creatures living in the Valley.' FROM games WHERE igdb_id = 34992 ON CONFLICT (game_id, language_code) DO NOTHING;
