INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Let''s Explore the Airport', 'Let''s Explore the Airport captures all of the fun, energy, and excitement of a real, working airport. Kids can check out the ticket counter in the main terminal, work the controls in the cockpit of the Concord, and see how the ground crew prepares the planes. Players can even sneak behind the scenes and find out where the baggage really goes. And that''s just the beginning of this incredible tour.' FROM games WHERE igdb_id = 35469 ON CONFLICT (game_id, language_code) DO NOTHING;
