INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokaboo', 'Pokaboo is a simply haunting puzzle game in which you join blobs of the same color together. As the ghost, you will work in increasingly challenging layouts to combine matching colors into abstract shapes from all around the board. As you merge colors together successfully, that particular color will disappear, bringing you closer to level completion.' FROM games WHERE igdb_id = 197851 ON CONFLICT (game_id, language_code) DO NOTHING;
