INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dungeon-crawl', 229226, '2015-05-24', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/sckccr.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeon Crawl', 'Dungeon Crawl is a simplified maze RPG game similar to rogue-like RPGs, except that in Dungeon Crawl the dungeon is always the same and not randomly generated. To make progress through the dungeon and reach the next dungeon levels, the player has to find keys to unlock doors and find buttons which opens up formerly inaccessible sections. Typical fantasy monsters roam the dungeon, often blocking your path. Killing them gives XP, which is needed to further improve your characters attack and defense values.' FROM games WHERE igdb_id = 229226 ON CONFLICT (game_id, language_code) DO NOTHING;
