INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crazy Steam Bros 2', 'Crazy Steam Bros is a classical horizontal shoot''em up inspired by the gameplay of old arcades. Anton and Dupont are brothers, inventors, and a little mad also! With the help of their landlady, Miss Lily, they must defeat the evil Baron and their hordes of moustached soldiers. Fly the "SteaMobile" trough five levels of steampunk action. Traverse cities, jungles, caves and more. Collect Power-Ups for your machine and defeat the bad tempered bosses before the tea time!' FROM games WHERE igdb_id = 35640 ON CONFLICT (game_id, language_code) DO NOTHING;
