INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fairytale Encore', 'This is the fandisc to Liar-soft’s mysterious fairy tale horror Fairytale Requiem, including a main story featuring new heroine Dorothy which takes place before the events of the original game, and three side stories for Odil/Odette, Rapunzel and Gerda. The isolated medical center “Paradise” treats those that are afflicted with ‘fairytale syndrome’, where they believe they are fairy tale characters. The young doctor Ikeno, formerly an aspiring fairy tale writer who had his dreams crushed, couldn’t keep up with the patients who acted out their fantasies as they wished.' FROM games WHERE igdb_id = 59199 ON CONFLICT (game_id, language_code) DO NOTHING;
