INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Max Bradshaw and the Zombie Invasion', 'Meet Max Bradshaw, intrepid adventurer and all around hero. Then help him save the world from a zombie invasion in this modern action adventure game designed to bring back some of those classic gaming feelings.' FROM games WHERE igdb_id = 197250 ON CONFLICT (game_id, language_code) DO NOTHING;
