INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Galactic Nemesis', 'Aliens are invading the galaxies and you''re the only hope. Battle waves of alien races and defeat mega bosses with your powerful galactic ship. Each world offers a new set of challenges, and new species of fire shooting aliens. Upgrade your ship to help your conquer the challenges. Compete in almost 50 stages, then attempt each world''s endurance mode to see if you have what it takes to save each galaxy.' FROM games WHERE igdb_id = 197252 ON CONFLICT (game_id, language_code) DO NOTHING;
