INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Faraway Story', 'In Faraway Story, you play as Pia, a pharmacist-in-training with the goal of curing a disease plaguing Port Fina. Collect ingredients, craft items to sell at your shop, acquire party members... and investigate that strange landmass floating over Port Fina: the Faraway Continent. Game includes a Part 1 and Part 2; Part 1 is complete.' FROM games WHERE igdb_id = 125409 ON CONFLICT (game_id, language_code) DO NOTHING;
