INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Broken Sword 5: The Serpent''s Curse - Premium Edition', 'Broken Sword 5: The Serpent''s Curse is a classical point & click adventure. It abandons 3D graphics and direct control which were used in the two predecessors and returns to the style of the first two games. The only major technical differences are a higher resolution and that the characters are modelled instead of drawn.' FROM games WHERE igdb_id = 136170 ON CONFLICT (game_id, language_code) DO NOTHING;
