INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Satellina', 'Satellina: a simple and elegant "puzzle in motion" that can be understood within 10 seconds by a five-year-old, but has also driven adults to obsessive lengths. It has a clean, minimalistic look, a catchy original synthpop soundtrack, a challenging but rewarding (and never punitive) difficulty curve, and a timed structure that''s perfect for speedrunning.' FROM games WHERE igdb_id = 128557 ON CONFLICT (game_id, language_code) DO NOTHING;
