INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sketchcross', 'Sketchcross is a logic puzzler based on the nonogram ruleset. If you''re not familiar, think of a mix between crosswords and sudoku. You''re given number clues on the rows and columns to help sketch in the corresponding squares on the grid. Doing so starts to reveal the picture you''re creating.' FROM games WHERE igdb_id = 52824 ON CONFLICT (game_id, language_code) DO NOTHING;
