INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Combo Queen', 'Combo Queen is a fast-paced hack and slash action RPG hybrid runner. The game features a unique combo and parry system which involves precise timing and reaction based gameplay. Your main objective is to plow through as many monsters as possible while taking on numerous challenges. Level up, learn new combo sets, and unlock a variety of powerful equipment for the main character, Queen! If you’re up for the challenge, download Combo Queen and conquer the Giant Clan!' FROM games WHERE igdb_id = 46500 ON CONFLICT (game_id, language_code) DO NOTHING;
