INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pluck', 'Pluck is a fast paced twin stick shoot ''em up that supports up to 4 players. Venture through procedurally generated dungeons, vanquishing enemies along the way. Collect various items and abilities to become more powerful on your run. Be careful, though, once you''re dead it''s game over. How long will you last?' FROM games WHERE igdb_id = 35986 ON CONFLICT (game_id, language_code) DO NOTHING;
