INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Adventure Escape: Asylum', 'Can you remember your past and escape the Asylum? Anna wakes up one day in an asylum with hazy memories of her past. Soon, it’s clear that something has gone very, very wrong at the Byers Institute. In fact, there is a killer on the loose! As Anna tries to escape, a mysterious girl begins to appear with helpful warnings. Is the girl a figment of Anna’s delusions? Or is there more to Anna’s past than she knows?' FROM games WHERE igdb_id = 123440 ON CONFLICT (game_id, language_code) DO NOTHING;
