INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ninjahtic', 'Ninjahtic is an action/adventure platformer with elements of puzzle-solving and stealth. While it''s progression is linear, the open-ended nature of every level requires exploration of an abandoned civilization located atop floating islands. Usage of the environment also plays a key role when solving puzzles and dispatching enemy robots throughout.' FROM games WHERE igdb_id = 34887 ON CONFLICT (game_id, language_code) DO NOTHING;
