INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ghost in the Machine', 'Ghost in the Machine is about the player''s escape from a run-down factory following a large explosion. In the dark factory there are many dangerous machines that must be minded in order to not be crushed or mechanically separated. Inspired by 1980s platformer-genre games, Ghost in the Machine features true low-res graphics and an original chiptune soundtrack. It is also difficult, yet rewarding.' FROM games WHERE igdb_id = 35475 ON CONFLICT (game_id, language_code) DO NOTHING;
