INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Voice of Vamana', 'The year is 2130. A vessel from interstellar space - the first concrete proof that humanity is not alone in the universe - has entered our solar system and is hurtling towards the sun. As the only ship capable of reaching it in time, you are tasked with discovering it''s purpose. Venture inside the allegedly lifeless thing and divine what you can.' FROM games WHERE igdb_id = 141743 ON CONFLICT (game_id, language_code) DO NOTHING;
