INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yuuki Yuna wa Yuusha de Aru S', 'Yuuki Yuna wa Yuusha de Aru S is a Japanese visual novel based on the Yuuki Yuna wa Yuusha de Aru franchise. The story follows the five female club members of the Sanshu Middle School Hero Club, who are tasked of protecting the world from mysterious monsters known as Vertex. The visual novel features ten different scenarios original to the game and is fully voiced by the original cast. It was released as an extra with the sixth DVD and Blu-ray volumes for the TV anime.' FROM games WHERE igdb_id = 11788 ON CONFLICT (game_id, language_code) DO NOTHING;
