INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Boggle', 'So you think you’re fast at finding words? Prove it! Challenge yourself or up to 3 friends online in a refreshed, updated Boggle experience. There’s still the same Boggle you like. You can also play with a suite of different variants and house rules to really shake things up! Search fast and act faster… it’s an all-new way to play Boggle!' FROM games WHERE igdb_id = 59965 ON CONFLICT (game_id, language_code) DO NOTHING;
