INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'City Quest', 'Welcome back the past with City Quest, a powerful love letter to the adventure games of yesteryear. Follow a simple farmer boy as he tries to make a name for himself in the big city. Players can enjoy four storylines - Hobo, Mafia, Politician, and Lady of the Night, each with their own unique cast of misfits to help you along the way (as well as several different endings for each). Packed with often offensive and always absurd humor, this game will tickle the funnybone and anger the gods.' FROM games WHERE igdb_id = 17565 ON CONFLICT (game_id, language_code) DO NOTHING;
