INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Professional Lumberjack 2015', 'Face the hard work of real lumberjacks as you control and operate various small and large machinery at your disposal. From huge Feller Buncher and Harvesters that debranch and cut up the trunks, to tractors, cranes, trucks and trailers for the transportation of the chopped logs. In your own expandable mill you will be able to produce different goods from the raw material and sell your product output for profit.' FROM games WHERE igdb_id = 9213 ON CONFLICT (game_id, language_code) DO NOTHING;
