INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Revolution Under Siege Gold', 'Revolution Under Siege GOLD is the first complete historical simulation on PC of the Russian Civil War between 1917 and 1923. A wealth of historical events and geopolitical options, real or possible according to the player''s choices, will bring a realistic tempo to the maneuver of your forces and those of your opponents. From the Baltic to the shores of the Pacific and through the arid steppes of Central Asia, relive the biggest civil war ever!' FROM games WHERE igdb_id = 35146 ON CONFLICT (game_id, language_code) DO NOTHING;
