INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rocket Joust', 'Battle your friends for aerial supremacy in Rocket Joust! Jump in with up to 4 human or AI competitors on the one device, in a wild contest to knock each other from the sky. Play across multiple levels and modes, using a host of quirky characters, and show your friends who the best jouster is!' FROM games WHERE igdb_id = 174183 ON CONFLICT (game_id, language_code) DO NOTHING;
