INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Circuit Boxing', 'World Circuit Boxing is a boxing management game with RPG, strategy, and simulation elements. WCB lets you take over a gym or control the entire boxing world. Watch your fighters in the ring, working their corners; or equip and train them, and let them handle their own business. In World Circuit Boxing, you have the ability to restore the sweet science to the days when the only ducking was done in the ring!' FROM games WHERE igdb_id = 80919 ON CONFLICT (game_id, language_code) DO NOTHING;
