INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Enigma: An Illusion Named Family', 'The hero of the game, Minhyuk, loses his father in an accident in his childhood. He spends his adolescence in guilt, while his siblings jump into a family feud over the inheritance.One day, an unexpected blackout takes place in the mansion, and Minhyuk has to overcome the strange and often fatal incidents to find out the truth behind.' FROM games WHERE igdb_id = 35612 ON CONFLICT (game_id, language_code) DO NOTHING;
