INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Othello Masters', 'Players take turns placing disks on the board with their assigned color facing up. During a play, any disks of the opponent''s color that are in a straight line and bounded by the disk just placed and another disk of the current player''s color are turned over to the current player''s color. The object of the game is to have the majority of disks turned to display your color when the last playable empty square is filled.' FROM games WHERE igdb_id = 175529 ON CONFLICT (game_id, language_code) DO NOTHING;
