INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rising Thunder', 'Rising Thunder is a free-to-play fighting game that uses simplified controls in contrast to most 2D Fighting Games which utilize motion or charge commands. This is to make the game more accessible while still being deep and balanced, being capable of standing up to years of high level competitive play. There are eight buttons in total which consist of three normals, three specials, an Overdrive/Super, and a throw. Each character has a listed fighting style and level of difficulty.' FROM games WHERE igdb_id = 14705 ON CONFLICT (game_id, language_code) DO NOTHING;
