INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Two Eyes', 'Two Eyes is a transport puzzle where the objective is to unite the two eyes together. You can move the eyes by swiping, which will move both of them at the same time. If one eye can''t move, the other one still can. Navigate around walls, push blocks, and avoid traps in each of the 30 levels to unite the two eyes with each other. Enjoy uninterrupted play with no ads and no in app purchases.' FROM games WHERE igdb_id = 175271 ON CONFLICT (game_id, language_code) DO NOTHING;
