INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Militia', 'Militia is a tight turn-based strategy game that brings the thrill of victory to single-player. It''s simple to pick up, and from the moment you start, you''ll be learning and improving -- building your skills, learning new strategies, and ranking up on the single player ladder. And as you do, the game evolves with you, providing a worthy challenge every time. Militia also features procedurally generated levels so the challenge stays fresh.' FROM games WHERE igdb_id = 34028 ON CONFLICT (game_id, language_code) DO NOTHING;
