INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MotorSport Revolution', 'Motorsport Revolution is a single-player, physics-based racing game inspired by classic console racing games, as well as the popular Le Mans Series, which is considered the most challenging sport racing class in the world. With these influences in mind, we’re creating an epic immersive VR motorsport racing experience where players race the world’s top production-class race cars in the ultimate test on the world’s most difficult tracks.
