INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Game of Roads', 'Settle on tiles, connect them with roads. Build up their values by connecting multiple tiles to your capitals. In Duel mode capture enemy tiles by building strength where its needed. Tiles are turned in a new order and randomized for each game. Earn achievements and make your way to the top of the world-wide leaderboards!' FROM games WHERE igdb_id = 174364 ON CONFLICT (game_id, language_code) DO NOTHING;
