INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Go Kart Safari', 'In Go Kart Safari players must guide a little adventurous tourist on a heart-pumping safari expedition through treacherous terrain. The main objective is speed but players can boost their scores by snagging a few map pieces and artifact souvenirs along the way. Although the scenery is mesmerizing players can’t allow themselves to get distracted, this bumpy road is scattered with obstacles that can slow them down.' FROM games WHERE igdb_id = 175190 ON CONFLICT (game_id, language_code) DO NOTHING;
