INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grim Tales 8: The Final Suspect', 'Ms. Gray, an unrivaled detective with ability to go to the past, is in danger. They find a corpse in her house. She doesn''t remember the preceding events and has no idea who the murderer is. She is the prime suspect. Go back in time and find out who is the murderer in Grim Tales: The Final Suspect.' FROM games WHERE igdb_id = 140299 ON CONFLICT (game_id, language_code) DO NOTHING;
