INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blessed Ones: The Magic Wolves', 'Blessed Ones: The Magic Wolves is a silly little fairy tale about wolves (magic ones, obviously) and pigs and adventurers, coming in the form of a japanese-style RPG focused on strategic turn-based combat and party building. It is goofy, flexible, difficult, emergent, and open, in more ways than you might expect! Build your party as you explore rural Sleeping Owl Island, finding treasures, making new friends, saving the day--or just ignoring all the problems and gunning straight for the final boss!' FROM games WHERE igdb_id = 33960 ON CONFLICT (game_id, language_code) DO NOTHING;
