INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('de-ontdekker-en-het-mysterie-van-de-diamanten-scarabee', 268124, '2015-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9q38.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'De Ontdekker en het mysterie van de Diamanten Scarabee', 'De Ontdekker en het mysterie van de Diamanten Scarabee you play the role of Ben the Archaeologist who is searching for the Temple of the Diamond Scarab. Once he is in the temple he meets Tiri, an enchanting Egyptian princess. Going through a maze of underground passages they look for ancient Egyptian treasures and confront various challenges. The Guardian leads them step by step to the exit. The game is played on a Balance Board, a standard Wii accessory. With this you can move through the maze, find treasures and enter challenging situations. Since this is the first game in the world developed jointly for visually impaired, blind and fully sighted children, the game can be played in Dutch and in English.' FROM games WHERE igdb_id = 268124 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 268124 AND c.slug = 'little-chicken-game-company-bv' ON CONFLICT DO NOTHING;
