INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SingStar: Frozen', 'SingStar: Frozen is a karaoke game based on the animated movie Frozen. Except for the song Let It Go from Demi Lovato, which is the available in all language version, the other nine songs are translated and taken directly from the movie (including dialogue). There are no changes to the gameplay formula: player(s) sing into a microphone and the game gives points based on the performance. It is only rated if the correct not is hit at the correct time; the sung words or octave does not play into the result.' FROM games WHERE igdb_id = 86080 ON CONFLICT (game_id, language_code) DO NOTHING;
