INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nevertales: The Beauty Within', 'Just when you were finally done with work for the day, a stranger comes knocking loudly at your door. When you answer there''s no one... no one except a helpless baby abandoned on your doorstep. You follow after the stranger, hoping to find some answers but are drawn into a mystery that beckons you into a castle-like mansion. Who does the baby belong to? Why were you chosen?' FROM games WHERE igdb_id = 140203 ON CONFLICT (game_id, language_code) DO NOTHING;
