INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jagmatch', 'Jagmatch is an Atari Jaguar homebrew in which the player has to match Atari computers and consoles to games considered most iconic for each system. Essentially, it requires good short-term memory, but also solid long-term memory as far as Atari gaming history is concerned! To reveal a tile, press A on the controller.' FROM games WHERE igdb_id = 301769 ON CONFLICT (game_id, language_code) DO NOTHING;
