INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Real Boxing 2', 'Discover a whole new world of combat sports games. As a newbie boxer, challenge experienced opponents and try to win and score a KO! Explore the world of boxing and make your way to the top. You can become the boxing champion, the best warrior of all time! Discover what you''re made of, and try to climb to the top. Become the ultimate champion! Use jabs, hooks, uppercuts & combine them into devastating combos.' FROM games WHERE igdb_id = 186914 ON CONFLICT (game_id, language_code) DO NOTHING;
